import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { cache } from 'react'
import { BackButton } from '@/components/NavigationButtons'
import { getComments, getPost, getPosts, type Post } from '@/lib/posts'

type Params = { id: string }

type BlogPostProps = {
  params: Promise<Params>
}

// ISR: regenerate each post at most every 5 minutes.
export const revalidate = 300

// Replaces `fallback: 'blocking'`: ids not returned by `generateStaticParams`
// are rendered on demand and then cached.
export const dynamicParams = true

// Replaces `getStaticPaths`.
export async function generateStaticParams(): Promise<Params[]> {
  const posts = await getPosts()

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

// Shared by `generateMetadata` and the page so the post is only fetched once
// per request. Mirrors the old `getStaticProps` returning `notFound: true`.
const loadPost = cache(async (id: string): Promise<Post> => {
  try {
    return await getPost(id, { next: { revalidate: 300 } })
  } catch {
    notFound()
  }
})

export async function generateMetadata({
  params,
}: BlogPostProps): Promise<Metadata> {
  const { id } = await params
  const post = await loadPost(id)
  const description = post.body.substring(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: BlogPostProps) {
  const { id } = await params
  const post = await loadPost(id)
  const comments = await getComments(id, { next: { revalidate: 300 } }).catch(
    () => notFound()
  )

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

