import { useEffect } from 'react'
import './globals.css'

// Handles errors thrown in the root layout itself. It replaces the root layout
// when active, so it must render its own <html> and <body>.
export default function GlobalError({
  error,
  retry,
}: {
  error: Error & { digest?: string }
  retry: () => void
}) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <html lang="en">
      <body>
        <title>Error - My Blog</title>
        <div className="error-page">
          <h1>An error occurred</h1>
          <p>Sorry, something went wrong.</p>
          <button onClick={() => retry()}>Try again</button>
        </div>
      </body>
    </html>
  )
}

