// Methods without an exported handler automatically respond with 405.

type PostRouteContext = {
  params: Promise<{ id: string }>
}

type UpdatePostBody = {
  title?: string
  content?: string
}

export async function GET(_request: Request, { params }: PostRouteContext) {
  const { id } = await params

  // Simulate fetching a single post
  const post = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(request: Request, { params }: PostRouteContext) {
  const { id } = await params
  const { title, content } = (await request
    .json()
    .catch(() => ({}))) as UpdatePostBody

  // Simulate updating a post
  const updatedPost = {
    id: parseInt(id),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(_request: Request, { params }: PostRouteContext) {
  const { id } = await params

  // Simulate deleting a post
  return Response.json({ message: `Post ${id} deleted successfully` })
}

